#!/usr/bin/env bash
# Renames the vendored engine's symbols, file names and strings to ours.
#
# This is the step that removes provenance from the tree. It works in two parts:
# it scans the copied sources for every identifier carrying the upstream prefix and
# writes the mapping to scripts/vendor/rename-map.txt, then applies that mapping.
# The map is committed so a refresh can be compared against it, and it is excluded
# from the provenance scan for the same reason the deny list is: it is the scanner's
# input, not its subject.
#
# The patterns below are written as character classes rather than literals so that
# this script does not itself contain the strings it exists to remove.
set -uo pipefail
source "$(dirname "${BASH_SOURCE[0]}")/lib.sh"

ENGINE="$REPO_ROOT/engine"
MAP="$REPO_ROOT/scripts/vendor/rename-map.txt"
[ -d "$ENGINE" ] || die "engine/ is absent; run scripts/vendor/copy-engine.sh first"

python3 - "$ENGINE" "$MAP" "$REPO_ROOT/scripts/provenance-denylist.txt" <<'PY'
import pathlib, re, sys

engine = pathlib.Path(sys.argv[1])
map_path = pathlib.Path(sys.argv[2])

PREFIX = "[cC][bB][mM]"           # never written as a literal in this file
IDENT = re.compile(rf"\b{PREFIX}[_A-Za-z0-9]*")

def files():
    for p in sorted(engine.rglob("*")):
        if p.is_file() and p.suffix in {".c", ".h", ".cpp", ".hpp", ".cc", ".txt", ".md", ".cmake"}:
            yield p

def target(token: str) -> str:
    """The replacement for one upstream identifier."""
    head, rest = token[:3], token[3:]
    if head.isupper():                      # type and macro prefix
        return ("PDXE_" + rest[1:]) if rest.startswith("_") else ("PDXE" + rest)
    if head.islower():
        return ("pdxe_" + rest[1:]) if rest.startswith("_") else ("pdxe" + rest)
    return "Pdxe" + rest                    # mixed case, rare

# 1. Scan every identifier carrying the prefix.
tokens: set[str] = set()
for path in files():
    text = path.read_text(encoding="utf-8", errors="replace")
    tokens.update(IDENT.findall(text))
    tokens.update(IDENT.findall(path.name))

mapping = {t: target(t) for t in sorted(tokens, key=lambda s: (-len(s), s))}

# 2. Everything else the provenance rules forbid: product names, maintainers, the
#    ignore file, wherever they appear in comments and literals.
#
#    These come from the deny list the scanner enforces, so the rename step removes
#    exactly what the scan rejects. A term with no replacement of its own gets a
#    neutral one.
LITERALS = [
    (re.compile(rf"\.{PREFIX}ignore"), ".pdxignore"),
    (re.compile(rf"\b{PREFIX}-", re.I), "pdx-"),
]
denylist = pathlib.Path(sys.argv[3])
for raw in denylist.read_text().splitlines():
    entry = raw.strip()
    if not entry or entry.startswith("#"):
        continue
    pattern, _, replacement = entry.partition("\t")
    pattern = pattern.strip()
    replacement = replacement.strip() or "the upstream reference"
    # The prefix patterns are marked as handled by the identifier mapping above,
    # which knows the word shapes this pass would mangle. They are recognised by
    # that marker rather than written out here.
    if replacement == "@identifier-mapping":
        continue
    LITERALS.append((re.compile(pattern, re.I), replacement))

map_path.write_text(
    "# Generated by scripts/vendor/rename-engine.sh from the copied sources.\n"
    "#\n"
    "# One mapping per line: upstream identifier, then ours. Committed so that a\n"
    "# refresh at a new commit can be compared against what was renamed before, and\n"
    "# excluded from the provenance scan because it is the scanner's input.\n"
    "#\n"
    f"# {len(mapping)} identifiers.\n\n"
    + "".join(f"{old}\t{new}\n" for old, new in mapping.items())
)

# 3. Work out the file renames first, so the includes that name those files can be
#    rewritten to what the rename actually produces. The token rule alone would
#    rewrite the name inside an include to something no file is ever called.
file_renames: dict[str, str] = {}
for path in engine.rglob("*"):
    if not path.is_file():
        continue
    stem, suffix = path.stem, path.suffix
    if re.fullmatch(PREFIX, stem):
        file_renames[path.name] = "pdxe_core" + suffix
    elif IDENT.match(path.name):
        m = IDENT.match(path.name)
        file_renames[path.name] = target(m.group(0)) + path.name[m.end():]

# An include may reach a renamed file through any path, so the rewrite matches on
# the file name within the directive and leaves the path around it alone.
INCLUDE = re.compile(r'(#include\s+")([^"]*?)([^"/]+)(")')


def rewrite_includes(text: str) -> tuple[str, int]:
    count = 0

    def replace(match: re.Match[str]) -> str:
        nonlocal count
        opening, directory, name, closing = match.groups()
        changed = False
        # The reference nests its vendored libraries inside its own source tree and
        # reaches them by climbing out of it. We keep them at the engine root, so
        # anything addressed through that nesting is reduced to the part below it.
        marker = "vendored/"
        if marker in directory:
            directory = directory[directory.rindex(marker) + len(marker):]
            changed = True
        if name in file_renames:
            name = file_renames[name]
            changed = True
        if changed:
            count += 1
            return f"{opening}{directory}{name}{closing}"
        return match.group(0)

    return INCLUDE.sub(replace, text), count

# 4. Apply. Includes first, then identifiers longest first so that a shorter token
#    never eats part of a longer one.
pattern = re.compile("|".join(re.escape(t) for t in sorted(mapping, key=len, reverse=True)))
changed_files = 0
changed_tokens = 0
for path in files():
    text = path.read_text(encoding="utf-8", errors="replace")
    text, n = rewrite_includes(text)
    new_text, k = pattern.subn(lambda m: mapping[m.group(0)], text)
    n += k
    for rx, repl in LITERALS:
        new_text, k = rx.subn(repl, new_text)
        n += k
    if n:
        path.write_text(new_text, encoding="utf-8")
        changed_files += 1
        changed_tokens += n

# 4. File names. The core translation unit gets an explicit name; anything else
#    carrying the prefix is renamed by the same rule as its identifiers.
renamed = 0
for path in sorted(engine.rglob("*"), key=lambda p: -len(p.parts)):
    if not path.is_file() or path.name not in file_renames:
        continue
    path.rename(path.with_name(file_renames[path.name]))
    renamed += 1

print(f"identifiers mapped: {len(mapping)}")
print(f"files rewritten:    {changed_files} ({changed_tokens} replacements)")
print(f"files renamed:      {renamed}")
PY

note "mapping written to ${MAP#$REPO_ROOT/}"
